from pathlib import Path
import importlib.util
root=Path(__file__).parent
outroot=root.parent if root.name=='verification' else root
spec=importlib.util.spec_from_file_location('base',root/'build.py');base=importlib.util.module_from_spec(spec);spec.loader.exec_module(base)
source='https://www.ngi.no/globalassets/bilder/forskning-og-radgivning/bygg-og-anlegg/q-handbook_2025_english_final.pdf'
f=base.field
controls='<h3>1. Геометрия · свод полукругом</h3><div class="fields">'
for a in [('span','Ширина выработки B, м',5,1,30),('wall','Высота прямой стены h, м',2,0,30),('length','Длина участка, м',100,1,10000),('esr','ESR · по назначению',1.6,.5,5)]:controls+=f(*a)
controls+='</div><p class="sub">Полная высота = h + B/2. Для De используется высота прямой стены. ESR=1,6 — постоянная горная выработка, категория C.</p><label><input type="checkbox" id="permanent" checked style="width:auto"> Постоянная горная выработка (C)</label><h3>2. Параметры массива</h3><div class="fields">'
for a in [('rqd','RQD, %',60,0,100),('jn','Jn · трещиноватость',9,.5,60),('jr','Jr · шероховатость',2,.5,4),('ja','Ja · заполнение',2,.75,20),('jw','Jw · вода',1,.05,1),('srf','SRF · напряжения / ослабление',1,.5,400)]:controls+=f(*a)
controls+='</div><p class="sub">Параметры вводятся по картированию и таблицам NGI. Jn — итоговое значение с учётом места выработки; поправки портала/пересечения автоматически не добавляются. SRF не определяется только глубиной.</p><label><input type="checkbox" id="challenging" style="width:auto"> Удары, выдавливание, набухание, опасные блоки или иные сложные условия</label>'
controls+=f'<h3>3. Требования инженера</h3><p class="sub">Откройте <a href="{source}#page=34" target="_blank" rel="noopener">диаграмму NGI, рис. 4-1 ↗</a> с рассчитанными Q и De. Введите требования для рассматриваемого профиля. Начальные числа ниже — учебные, не результат считывания диаграммы.</p><div class="fields">'
for a in [('requiredSpace','Максимальный шаг анкеров, м',1.5,.3,5),('requiredLength','Минимальная длина анкера, м',2.4,1,15),('requiredThickness','Минимальный слой Sfr, мм',75,0,500)]:controls+=f(*a)
controls+='</div><label><input type="checkbox" id="confirmed" style="width:auto"> Проверены диаграмма, длина анкеров и применимость требований к своду и стенам</label>'
for k,title,vals in [('a','A · базовый вариант',(1.5,2.4,75)),('b','B · усиленный вариант',(1.2,3,100))]:
 controls+='<h3>'+title+'</h3><div class="fields">'
 for suffix,label,val,lo,hi in [('Space','Шаг по контуру и вдоль, м',vals[0],.3,5),('Length','Длина анкера, м',vals[1],1,15),('Thickness','Набрызгбетон Sfr, мм',vals[2],0,500)]:controls+=f(k+suffix,label,val,lo,hi)
 controls+=f'</div><label><input type="checkbox" id="{k}Mesh" '+('checked' if k=='b' else '')+' style="width:auto"> Дополнительная сетка</label>'
controls+='<h3>4. Условные расценки · USD</h3><div class="fields">'
for a in [('boltRate','Анкеры с установкой, USD/м анкера',35,0,10000),('concreteRate','Sfr с нанесением, USD/м³ смеси',250,0,10000),('meshRate','Сетка с установкой, USD/м²',12,0,1000),('rebound','Отскок: доля поданной смеси, %',15,0,60)]:controls+=f(*a)
controls+='</div><div class="actions"><button id="calc">Рассчитать варианты</button><button id="reset" class="secondary">Учебный пример</button></div>'
output='''<section class="panel"><span class="badge">UNDERGROUND SUPPORT / Q → GEOMETRY → QUANTITIES</span><h2>Крепление горной выработки</h2><div id="stamp" class="stamp"></div><div id="stats" class="stats"></div><div id="conclusion" class="notice"></div><div id="coordinates"></div></section><section class="panel"><h2>Схема крепления · вариант A</h2><div id="section"></div><p class="sub">Свод — полуокружность; стены вертикальные; почва не крепится. Радиальные анкеры показаны условно, без проверки пересечения блоков. Реальное направление и длина требуют структурной модели.</p></section><section class="panel"><h2>Сравнение вариантов</h2><div id="variants"></div><p class="sub">Соответствие относится только к введённым шагу, длине и толщине. Энергоёмкость Sfr, несущая способность анкеров, сцепление, коррозия и срок службы проверяются отдельно. Более высокая цена не доказывает большую безопасность.</p></section><section class="panel"><h2>Что изменится при обводнении</h2><div id="water"></div><p class="sub">Меняется только Jw. Это анализ чувствительности Q, а не расчёт фильтрации. Требования крепления при каждом состоянии считываются заново.</p></section><section class="panel"><h2>Методика и исходные данные</h2><details><summary>Формулы, ограничения и источники</summary><div class="formula">Q = max(RQD,10)/Jn × Jr/Ja × Jw/SRF<br>De свода = max(B,h)/ESR; De стен = h/ESR<br>P = πB/2 + 2h; площадь = P × длина участка<br>Анкеров в ряду = ceil(P/шага); рядов = ceil(длины/шага)+1<br>V слоя = площадь × толщина/1000<br>V подачи = V слоя/(1−отскок/100)<br>Сетка = площадь × 1,10 (при выборе сетки)<br>Стоимость = метры анкеров × ставка + м³ подачи × ставка + м² сетки × ставка</div><p>Q и De рассчитываются автоматически. Шаг, длина и слой задаются инженером после проверки непрерывной диаграммы. Автоматическая оцифровка границ и назначение категории крепи не выполняются. Одинаковая крепь принимается на своде и обеих стенах; понижающая поправка Q для стен не применяется. При h &gt; B высота стены определяет также De свода. В категории C при Q ≤ 0,1 принимается ESR=1.</p><p>Число анкеров — укрупнённая ведомость: целые анкеры в равномерном контурном ряду, включая два торцевых ряда. Разбивка углов, доступность бурения и локальное усиление уточняются в проекте. Набрызгбетон — постоянный тонкий слой; объём по поверхности, без поправки на кривизну, шероховатость и заполнение пустот. Сетка включает условные 10% нахлёста; отскок относится к поданной смеси. Расценки учебные, без мобилизации, проходки, дренажа, инъекций, рам/RRS, налогов и прочих проектных работ.</p><p>Q &lt; 1, отмеченные сложные условия или выход за принятый диапазон просмотра (Q 0,001…1000; De 1…100) останавливают предварительный выбор. Расходы остаются видимыми для планирования. Q не является коэффициентом запаса. Требуется отдельная проверка блоков, нагрузок и анкеров; эта программа не выпускает паспорт крепления.</p><p>Источник: <a href="SOURCE" target="_blank" rel="noopener">NGI, Using the Q-system, April 2025</a>: раздел 2 (Q), 3.2 и табл. 3-1 (RQD), раздел 4.1 и табл. 4-1 (размер и ESR), раздел 4.2 и рис. 4-1 (диаграмма и длина), 4.2.2 (стены), 1.4 и 4.7 (ограничения). Номера страниц в PDF на 3 больше печатных.</p></details><div id="inputsReport"></div><button id="csv" class="secondary">Сравнение CSV</button><button id="print">Отчёт / PDF</button></section>'''.replace('SOURCE',source)
js=(root/'support-engine.mjs').read_text().replace('export function','function')+'''
let current=null;
function params(){const p=read();for(const id of ['permanent','challenging','confirmed','aMesh','bMesh'])p[id]=$(id).checked;return p;}
const defaults=params();
function section(p){const w=p.span,h=p.wall,r=w/2,L=p.aLength,scale=Math.min(500/(w+2*L),285/(h+r+L)),X=x=>370+x*scale,Y=y=>345-y*scale;let s='<svg viewBox="0 0 740 390" role="img" aria-label="Поперечное сечение выработки с анкерами"><rect width="740" height="390" fill="#edf1ed"/>';s+=`<path d="M${X(-r)} ${Y(0)}V${Y(h)}A${r*scale} ${r*scale} 0 0 1 ${X(r)} ${Y(h)}V${Y(0)}Z" fill="white" stroke="#147d9c" stroke-width="${Math.max(3,p.aThickness/1000*scale)}"/>`;for(let i=0;i<=8;i++){const a=Math.PI*i/8,x=r*Math.cos(a),y=h+r*Math.sin(a);s+=`<path d="M${X(x)} ${Y(y)}L${X(x+L*Math.cos(a))} ${Y(y+L*Math.sin(a))}" stroke="#bb642e" stroke-width="3"/>`;}for(let i=1;i<=3;i++)for(const sign of [-1,1])s+=`<path d="M${X(sign*r)} ${Y(h*i/4)}H${X(sign*(r+L))}" stroke="#bb642e" stroke-width="3"/>`;return s+`<text x="370" y="373" text-anchor="middle" font-size="14">B = ${f(w)} м · h стен = ${f(h)} м · L анкера = ${f(L)} м</text><text x="22" y="26" font-size="12">Синяя линия: Sfr ${f(p.aThickness,0)} мм · оранжевые: анкеры (условно)</text></svg>`;}
function calculate(){try{clearError();const p=params(),r=support(p);current={p,r};$('state').hidden=true;$('outputs').hidden=false;$('stamp').textContent='Рассчитано '+new Date().toLocaleString('ru-RU');$('stats').innerHTML=stat('Качество массива Q',f(r.Q,3),'полная формула, Jw и SRF учтены')+stat('Эквивалентный размер De',f(r.De,2),'свод; стены: '+f(r.Dw,2))+stat('Площадь крепления',f(r.area,1),'м² · ESR использован '+f(r.esr,2));$('conclusion').textContent=r.hold?'HOLD: сложные условия, Q < 1 или выход за диапазон. Требуется расширенная оценка; подбор остановлен.':!p.confirmed?'Ожидается проверка диаграммы NGI. Показанные размеры крепи — учебные; выбор варианта ещё не подтверждён.':r.best?'Вариант '+r.best+' дешевле среди вариантов, соответствующих введённым требованиям. Это предварительное сравнение, не проектное подтверждение устойчивости.':'Ни один вариант не соответствует всем введённым требованиям.';$('coordinates').innerHTML='<p class="sub">Для проверки рис. 4-1: Q = '+f(r.Q,4)+'; De свода = '+f(r.De,3)+'; De стен = '+f(r.Dw,3)+'. Для стен используйте фактическое Q и подтвердите применимость одинаковой крепи.</p>';$('section').innerHTML=section(p);$('variants').innerHTML=table(['Показатель','A','B'],[['Шаг, м',f(p.aSpace),f(p.bSpace)],['Длина анкера, м',f(p.aLength),f(p.bLength)],['Sfr, мм',f(p.aThickness,0),f(p.bThickness,0)],...['rows','perRow','bolts','boltMetres','installed','supplied','mesh','cost','costPerMetre'].map((k,i)=>[['Рядов','Анкеров в ряду','Анкеров, шт.','Длина всех анкеров, м','Объём слоя, м³','Подача смеси, м³','Сетка с нахлёстом, м²','Всего, USD','Стоимость на 1 м, USD'][i],...r.options.map(o=>f(o[k],i<3?0:2))]),['Три размерных требования',...r.options.map(o=>o.meets?'Соответствует':'Не соответствует')],['Предварительный выбор',...r.options.map(o=>o.eligible?(o.name===r.best?'Минимум стоимости':'Допустим к сравнению'):'Не подтверждён')]]);$('water').innerHTML=table(['Jw (сценарий)','Q','ESR','De свода'],[1,.66,.33,.1].map(jw=>{const a=support({...p,jw});return [f(jw,2),f(a.Q,3),f(a.esr,2),f(a.De,2)]}));$('inputsReport').innerHTML='<details><summary>Все введённые данные</summary>'+table(['Поле','Значение'],Object.entries(p).map(([k,v])=>[document.querySelector('label[for="'+k+'"]').textContent,typeof v==='number'?f(v,3):String(v)]))+'</details>';}catch(e){current=null;$('outputs').hidden=true;$('state').hidden=false;$('state').textContent='Проверьте исходные данные.';$('error').textContent=e.message;}}
function invalidate(){current=null;$('outputs').hidden=true;$('state').hidden=false;$('state').textContent='Данные изменены. Нажмите «Рассчитать варианты».';clearError();}
$('calc').onclick=calculate;$('reset').onclick=()=>{for(const [k,v] of Object.entries(defaults)){if(typeof v==='boolean')$(k).checked=v;else $(k).value=v;}calculate();};document.querySelectorAll('input').forEach(el=>el.addEventListener('input',()=>{if(['rqd','jn','jr','ja','jw','srf','span','wall','esr','permanent','challenging'].includes(el.id))$('confirmed').checked=false;invalidate();}));$('print').onclick=()=>{if(current)printReport();};$('csv').onclick=()=>{if(!current)return;download('support-comparison.csv','variant;bolts;bolt_m;shotcrete_supplied_m3;mesh_m2;USD;USD_per_m;requirements_met;eligible\\n'+current.r.options.map(o=>[o.name,o.bolts,o.boltMetres,o.supplied,o.mesh,o.cost,o.costPerMetre,o.meets,o.eligible].join(';')).join('\\n'),'text/csv;charset=utf-8');};calculate();
'''
# Give checkbox labels explicit associations for the report.
for k in ['permanent','challenging','confirmed','aMesh','bMesh']:
 controls=controls.replace('<label><input type="checkbox" id="'+k+'"','<label for="'+k+'"><input type="checkbox" id="'+k+'"')
html=base.wrap('Крепление горных выработок','03 / UNDERGROUND SUPPORT','Q-system NGI, проверка требований крепления и сравнение двух вариантов по расходу материалов и стоимости. Интерактивный инструмент предварительной оценки.',controls,output,js)
nav='<a href="underground-support.html">Крепление выработок</a>'
html=html.replace('<a href="mailto:eduard@ugmineplanner.com">',nav+'<a href="mailto:eduard@ugmineplanner.com">')
(outroot/'underground-support.html').write_text(html)
for name in ['stope-economics.html','dump-stability.html']:
 p=outroot/name;s=p.read_text();p.write_text(s.replace('<a href="mailto:eduard@ugmineplanner.com">',nav+'<a href="mailto:eduard@ugmineplanner.com">'))
